CREATE OR REPLACE FUNCTION private.org_fingerprint() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT md5(private.org_config()::text||coalesce((SELECT string_agg(row_to_json(x)::text,'|' ORDER BY row_to_json(x)::text) FROM user_roles x),'')||coalesce((SELECT string_agg(row_to_json(x)::text,'|' ORDER BY row_to_json(x)::text) FROM app_roles x),'')||coalesce((SELECT string_agg(row_to_json(x)::text,'|' ORDER BY row_to_json(x)::text) FROM profiles x),'')||coalesce((SELECT string_agg(row_to_json(x)::text,'|' ORDER BY row_to_json(x)::text) FROM base_title_role_links x),'')||coalesce((SELECT string_agg(row_to_json(x)::text,'|' ORDER BY row_to_json(x)::text) FROM biz_approval_workflows x),'')||coalesce((SELECT string_agg(row_to_json(x)::text,'|' ORDER BY row_to_json(x)::text) FROM biz_access_exceptions x),'')) $$;
CREATE OR REPLACE FUNCTION private.org_execution_ok() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM private.org_execution e JOIN private.org_previews p ON p.id=e.preview_id WHERE e.transaction_id=txid_current() AND e.actor_id=auth.uid() AND p.actor_id=auth.uid() AND p.applied_at IS NULL AND p.expires_at>clock_timestamp()) $$;
CREATE OR REPLACE FUNCTION private.org_projection_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.org_execution_ok() THEN RAISE EXCEPTION 'Thay đổi cơ cấu phải qua xem trước và xác nhận.';END IF; IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Không xóa lịch sử cơ cấu.';END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.biz_org_can_manage() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.is_active(auth.uid()) AND (public.is_super_admin(auth.uid()) OR public.biz_can(auth.uid(),'biz.org_manage') OR private.org_execution_ok()) $$;
CREATE OR REPLACE FUNCTION private.org_require(permission_ text,unit_ text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.org_execution_ok() OR NOT private.org_can(auth.uid(),permission_,unit_) THEN RAISE EXCEPTION 'Không có quyền trong phạm vi đơn vị này.';END IF; END $$;
CREATE OR REPLACE FUNCTION private.org_biz_appointment(x jsonb,new_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record;u uuid;d uuid;t uuid;s uuid;ts timestamptz;finish_ timestamptz;member_ uuid;BEGIN SELECT * INTO p FROM biz_positions WHERE id=(x->>'position_id')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'Chức vụ không tồn tại.';END IF;u:=(x->>'user_id')::uuid;d:=nullif(x->>'department_id','')::uuid;t:=nullif(x->>'team_id','')::uuid;s:=nullif(x->>'system_id','')::uuid;ts:=(x->>'started_at')::timestamptz;finish_:=nullif(x->>'ended_at','')::timestamptz;
 IF t IS NOT NULL THEN SELECT department_id INTO d FROM biz_teams WHERE id=t;END IF;IF d IS NOT NULL THEN SELECT system_id INTO s FROM biz_departments WHERE id=d;END IF; IF p.all_business THEN d:=NULL;t:=NULL;s:=NULL;END IF;
 INSERT INTO biz_appointments(id,position_id,user_id,system_id,department_id,team_id,scope_kind,started_at,ended_at,position_snapshot,actor_id) VALUES(new_id,p.id,u,s,d,t,p.unit_kind,ts,finish_,'{}',auth.uid());
 IF p.unit_kind IN ('department','team','individual') THEN member_:=private.biz_sync_member(u,d,t,ts,'concurrent'); UPDATE biz_member_affiliations SET appointment_id=new_id,ended_at=finish_ WHERE id=member_ AND appointment_id IS NULL;END IF;
 INSERT INTO biz_org_events(actor_id,action,payload) VALUES(auth.uid(),'canonical_appointment',jsonb_build_object('id',new_id,'new',x));RETURN new_id;END $$;
CREATE OR REPLACE FUNCTION private.org_commands(changes_ jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb;v jsonb;old_ record;title_ record;unit_ record;id_ text;parent_ text;at_ timestamptz;end_ timestamptz;category_ text;src_ text;scope_ text;d uuid;t uuid;s uuid;affected jsonb:='[]';before_ jsonb;after_ jsonb;expected_ jsonb;BEGIN
 IF jsonb_typeof(changes_) IS DISTINCT FROM 'array' OR jsonb_array_length(changes_) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Danh sách thay đổi không hợp lệ.';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(changes_) LOOP v:=x->'data';id_:=coalesce(nullif(v->>'id',''),gen_random_uuid()::text);
 IF x->>'action'='unit' THEN SELECT * INTO old_ FROM org_units WHERE id=id_;parent_:=nullif(v->>'parent_id',''); IF parent_ IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',parent_);END IF; IF old_.id IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',old_.id);IF old_.kind<>v->>'kind' THEN RAISE EXCEPTION 'Không đổi loại đơn vị đã tồn tại.';END IF; ELSIF parent_ IS NULL AND NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin tạo đơn vị gốc.';END IF;
 IF coalesce(trim(v->>'name'),'')='' OR v->>'kind' NOT IN ('company','block','system','department','team') THEN RAISE EXCEPTION 'Đơn vị không hợp lệ.';END IF; IF parent_=id_ OR private.org_contains(id_,parent_) THEN RAISE EXCEPTION 'Cơ cấu bị vòng lặp.';END IF;
 IF parent_ IS NOT NULL AND NOT EXISTS(SELECT 1 FROM org_units WHERE id=parent_ AND active) THEN RAISE EXCEPTION 'Đơn vị cha đã ngừng hoặc không tồn tại.';END IF;
 IF NOT coalesce((v->>'active')::boolean,true) AND (EXISTS(SELECT 1 FROM org_units WHERE parent_id=id_ AND active) OR EXISTS(SELECT 1 FROM org_assignments WHERE unit_id=id_ AND status<>'cancelled' AND (ends_at IS NULL OR ends_at>clock_timestamp()))) THEN RAISE EXCEPTION 'Đơn vị còn đơn vị con hoặc phân công hiệu lực/tương lai.';END IF;
 src_:=coalesce(old_.source,CASE WHEN private.org_contains('biz-block',parent_) THEN CASE v->>'kind' WHEN 'system' THEN 'biz_systems' WHEN 'department' THEN 'biz_departments' WHEN 'team' THEN 'biz_teams' ELSE 'canonical' END ELSE 'canonical' END);
 IF old_.id IS NOT NULL AND old_.parent_id IS DISTINCT FROM parent_ THEN INSERT INTO org_parent_history(id,unit_id,parent_id,starts_at,source,data) VALUES(gen_random_uuid()::text,id_,old_.parent_id,clock_timestamp(),'canonical',to_jsonb(old_));END IF;
 INSERT INTO org_units(id,parent_id,kind,name,active,source,source_id,data) VALUES(id_,parent_,v->>'kind',trim(v->>'name'),coalesce((v->>'active')::boolean,true),src_,id_,v) ON CONFLICT(id) DO UPDATE SET parent_id=excluded.parent_id,name=excluded.name,active=excluded.active,data=excluded.data,revision=org_units.revision+1;
 IF src_='biz_systems' THEN IF old_.id IS NOT NULL AND parent_ IS DISTINCT FROM old_.parent_id THEN RAISE EXCEPTION 'Hệ Kinh doanh giữ liên kết nghiệp vụ với Khối Kinh doanh.';END IF;INSERT INTO biz_systems(id,name,active) VALUES(id_::uuid,v->>'name',coalesce((v->>'active')::boolean,true)) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active;
 ELSIF src_='biz_departments' THEN IF parent_ IS NOT NULL AND NOT EXISTS(SELECT 1 FROM biz_systems WHERE id=parent_::uuid AND active) THEN RAISE EXCEPTION 'Phòng Kinh doanh cần Hệ nghiệp vụ hợp lệ.';END IF; IF old_.id IS NOT NULL AND old_.parent_id IS DISTINCT FROM parent_ AND EXISTS(SELECT 1 FROM biz_appointments WHERE department_id=id_::uuid AND status<>'cancelled' AND (ended_at IS NULL OR ended_at>clock_timestamp())) THEN RAISE EXCEPTION 'Phòng còn bổ nhiệm: cần đối chiếu phạm vi trước khi đổi Hệ.';END IF;INSERT INTO biz_departments(id,name,active,system_id) VALUES(id_::uuid,v->>'name',coalesce((v->>'active')::boolean,true),parent_::uuid) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active,system_id=excluded.system_id; IF parent_ IS NOT NULL AND (old_.id IS NULL OR old_.parent_id IS DISTINCT FROM parent_) THEN UPDATE biz_department_system_history SET ended_at=clock_timestamp() WHERE department_id=id_::uuid AND ended_at IS NULL;INSERT INTO biz_department_system_history(department_id,system_id,actor_id) VALUES(id_::uuid,parent_::uuid,auth.uid());END IF;
 ELSIF src_='biz_teams' THEN IF old_.id IS NOT NULL AND old_.parent_id IS DISTINCT FROM parent_ THEN RAISE EXCEPTION 'Nhóm đã có định danh nghiệp vụ; không đổi Phòng khi chưa đối chiếu phụ thuộc.';END IF;INSERT INTO biz_teams(id,department_id,name,active) VALUES(id_::uuid,parent_::uuid,v->>'name',coalesce((v->>'active')::boolean,true)) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active;END IF;affected:=affected||jsonb_build_array(id_);
 ELSIF x->>'action'='title' THEN SELECT * INTO old_ FROM org_titles WHERE id=id_;scope_:=coalesce(nullif(v->>'unit_id',''),'org-company');PERFORM private.org_require('org.manage_structure',scope_);IF old_.unit_id IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',old_.unit_id);END IF;
 IF coalesce(trim(v->>'name'),'')='' OR v->>'kind' NOT IN ('manager','staff') OR (v->>'level')::int NOT BETWEEN 0 AND 5 OR (v->>'capacity')::int<0 THEN RAISE EXCEPTION 'Chức vụ/cấp bậc không hợp lệ.';END IF;
 src_:=coalesce(old_.source,CASE WHEN coalesce(v->>'business_policy','none')<>'none' THEN 'biz_positions' ELSE 'canonical' END);
 IF src_='biz_positions' THEN IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chức vụ nghiệp vụ cần Super Admin xác nhận phạm vi.';END IF;INSERT INTO biz_positions(id,code,name,description,level,unit_kind,active,business_policy,all_business) VALUES(id_::uuid,v->>'code',v->>'name',coalesce(v->>'description',''),(v->>'level')::int,v->>'unit_kind',coalesce((v->>'active')::boolean,true),v->>'business_policy',coalesce((v->>'all_business')::boolean,false)) ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description,level=excluded.level,unit_kind=excluded.unit_kind,active=excluded.active,business_policy=excluded.business_policy,all_business=excluded.all_business,code=excluded.code;END IF;
 INSERT INTO org_titles(id,unit_id,name,code,level,kind,capacity,active,source,source_id,data) VALUES(id_,nullif(v->>'unit_id',''),v->>'name',v->>'code',(v->>'level')::int,v->>'kind',(v->>'capacity')::int,coalesce((v->>'active')::boolean,true),src_,id_,v) ON CONFLICT(id) DO UPDATE SET unit_id=excluded.unit_id,name=excluded.name,code=excluded.code,level=excluded.level,kind=excluded.kind,capacity=excluded.capacity,active=excluded.active,data=excluded.data,revision=org_titles.revision+1;affected:=affected||jsonb_build_array(scope_);
 ELSIF x->>'action'='assign' THEN SELECT * INTO unit_ FROM org_units WHERE id=v->>'unit_id'; SELECT * INTO title_ FROM org_titles WHERE id=v->>'title_id';IF unit_.id IS NULL OR title_.id IS NULL OR NOT unit_.active OR NOT title_.active THEN RAISE EXCEPTION 'Đơn vị/chức vụ đã ngừng hoặc không tồn tại.';END IF;PERFORM private.org_require('org.assign_staff',unit_.id);IF title_.kind='manager' OR title_.capacity=1 THEN PERFORM private.org_require('org.appoint_manager',unit_.id);IF v->>'user_id'=auth.uid()::text AND NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Không thể tự bổ nhiệm mình vào vị trí quản lý.';END IF;END IF;
 IF title_.unit_id IS NOT NULL AND title_.unit_id<>unit_.id THEN RAISE EXCEPTION 'Chức vụ không thuộc đơn vị này.';END IF;IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=(v->>'user_id')::uuid AND status='Đang hoạt động') THEN RAISE EXCEPTION 'Nhân viên chưa hoạt động.';END IF;
 at_:=coalesce(nullif(v->>'starts_at','')::timestamptz,clock_timestamp());end_:=nullif(v->>'ends_at','')::timestamptz;IF at_<clock_timestamp()-interval '10 minutes' OR end_<=at_ THEN RAISE EXCEPTION 'Không tạo phân công hồi tố hoặc thời hạn không hợp lệ.';END IF;category_:=coalesce(v->>'kind','primary');IF category_ NOT IN ('primary','concurrent') THEN RAISE EXCEPTION 'Chọn phân công chính hoặc kiêm nhiệm.';END IF;
 IF EXISTS(SELECT 1 FROM org_assignments WHERE unit_id=unit_.id AND title_id=title_.id AND status<>'cancelled' AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(at_,end_,'[)') AND user_id=(v->>'user_id')::uuid) THEN RAISE EXCEPTION 'Trùng phân công trong khoảng hiệu lực.';END IF;
 IF title_.capacity>0 AND (SELECT count(*) FROM org_assignments WHERE unit_id=unit_.id AND title_id=title_.id AND status<>'cancelled' AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(at_,end_,'[)'))>=title_.capacity THEN RAISE EXCEPTION 'Vị trí vượt số người tối đa trong khoảng hiệu lực.';END IF;
 IF category_='primary' AND EXISTS(SELECT 1 FROM org_assignments WHERE user_id=(v->>'user_id')::uuid AND category='primary' AND unit_id<>unit_.id AND status<>'cancelled' AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(at_,end_,'[)')) THEN RAISE EXCEPTION 'Chọn phân công nguồn cần kết thúc trước khi điều chuyển.';END IF;
 IF title_.source='biz_positions' THEN s:=NULL;d:=NULL;t:=NULL;IF unit_.kind='system' THEN s:=unit_.id::uuid;ELSIF unit_.kind='department' THEN d:=unit_.id::uuid;ELSIF unit_.kind='team' THEN t:=unit_.id::uuid;ELSIF unit_.kind<>'company' THEN RAISE EXCEPTION 'Chức vụ nghiệp vụ cần đơn vị tương thích.';END IF;PERFORM private.org_biz_appointment(jsonb_build_object('position_id',title_.id,'user_id',v->>'user_id','system_id',s,'department_id',d,'team_id',t,'started_at',at_,'ended_at',end_),id_::uuid);src_:='biz_appointments';category_:='appointment';ELSE src_:='canonical';END IF;
 INSERT INTO org_assignments(id,unit_id,title_id,user_id,category,starts_at,ends_at,source,source_id,data) VALUES(id_,unit_.id,title_.id,(v->>'user_id')::uuid,category_,at_,end_,src_,id_,v);affected:=affected||jsonb_build_array(unit_.id);
 ELSIF x->>'action' IN ('end','cancel') THEN SELECT * INTO old_ FROM org_assignments WHERE id=id_ FOR UPDATE;IF old_.id IS NULL THEN RAISE EXCEPTION 'Không tìm thấy phân công nguồn.';END IF;PERFORM private.org_require('org.assign_staff',old_.unit_id);SELECT * INTO title_ FROM org_titles WHERE id=old_.title_id;IF old_.category='legacy_manager' OR title_.kind='manager' THEN PERFORM private.org_require('org.appoint_manager',old_.unit_id);END IF;
 IF old_.status='cancelled' OR old_.ends_at<=clock_timestamp() THEN RAISE EXCEPTION 'Không sửa phân công đã kết thúc.';END IF;at_:=coalesce(nullif(v->>'ends_at','')::timestamptz,clock_timestamp());IF x->>'action'='cancel' THEN IF old_.starts_at<=clock_timestamp() THEN RAISE EXCEPTION 'Chỉ hủy phân công chưa hiệu lực.';END IF; ELSE IF at_<=old_.starts_at OR at_<clock_timestamp()-interval '10 minutes' THEN RAISE EXCEPTION 'Mốc kết thúc không hợp lệ.';END IF;END IF;
 IF old_.source='biz_appointments' THEN UPDATE biz_appointments SET ended_at=CASE WHEN x->>'action'='cancel' THEN ended_at ELSE at_ END,status=CASE WHEN x->>'action'='cancel' THEN 'cancelled' ELSE 'active' END WHERE id=old_.source_id::uuid; UPDATE biz_member_affiliations SET ended_at=CASE WHEN x->>'action'='cancel' THEN started_at+interval '1 microsecond' ELSE at_ END WHERE appointment_id=old_.source_id::uuid AND (ended_at IS NULL OR ended_at>at_);
 ELSIF old_.source='biz_department_members' THEN IF x->>'action'='cancel' THEN RAISE EXCEPTION 'Phân công Phòng cũ chưa có trạng thái hủy; cần đối chiếu riêng.';END IF;UPDATE biz_department_members SET ended_at=at_,effective_to=(at_ AT TIME ZONE 'Asia/Ho_Chi_Minh')::date WHERE id=old_.source_id::uuid;
 ELSIF old_.source='biz_team_members' THEN UPDATE biz_team_members SET ended_at=at_ WHERE id=old_.source_id::uuid;
 ELSIF old_.source='biz_member_affiliations' THEN UPDATE biz_member_affiliations SET ended_at=at_ WHERE id=old_.source_id::uuid;
 ELSIF old_.source='biz_management_assignments' THEN UPDATE biz_management_assignments SET ended_at=at_ WHERE id=old_.source_id::uuid;END IF;
 UPDATE org_assignments SET ends_at=CASE WHEN x->>'action'='cancel' THEN ends_at ELSE at_ END,status=CASE WHEN x->>'action'='cancel' THEN 'cancelled' ELSE 'active' END,revision=revision+1 WHERE id=id_;affected:=affected||jsonb_build_array(old_.unit_id);
 ELSIF x->>'action'='roles' THEN IF NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được chỉnh Role mặc định.';END IF;IF NOT EXISTS(SELECT 1 FROM org_titles WHERE id=id_) THEN RAISE EXCEPTION 'Chức vụ không tồn tại.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'roles') r WHERE coalesce((r->>'active')::boolean,false) OR r->>'role_id' IN ('role-admin','role-super-admin') OR NOT EXISTS(SELECT 1 FROM app_roles WHERE id=r->>'role_id')) THEN RAISE EXCEPTION 'Role chưa thể kích hoạt hoặc không hợp lệ.';END IF;SELECT source INTO src_ FROM org_titles WHERE id=id_;src_:=CASE WHEN src_='biz_positions' THEN 'biz' ELSE 'base' END;
 SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY role_id),'[]') INTO before_ FROM base_title_role_links l WHERE title_source=src_ AND title_id=id_; DELETE FROM base_title_role_links WHERE title_source=src_ AND title_id=id_;INSERT INTO base_title_role_links(title_source,title_id,role_id,is_primary,scope_kind,active,reason,updated_by) SELECT src_,id_,r->>'role_id',coalesce((r->>'is_primary')::boolean,false),coalesce(r->>'scope_kind','unit'),false,coalesce(v->>'reason','Cơ cấu tổ chức'),auth.uid() FROM jsonb_array_elements(v->'roles') r;SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY role_id),'[]') INTO after_ FROM base_title_role_links l WHERE title_source=src_ AND title_id=id_;INSERT INTO base_title_role_events(actor_id,title_source,title_id,reason,before_data,after_data) VALUES(auth.uid(),src_,id_,coalesce(v->>'reason','Cơ cấu tổ chức'),before_,after_);affected:=affected||jsonb_build_array('org-company');
 ELSE RAISE EXCEPTION 'Thao tác chưa được hỗ trợ an toàn: %',x->>'action';END IF;
 END LOOP; RETURN affected;END $$;
CREATE OR REPLACE FUNCTION public.org_change(_phase text,_revision bigint DEFAULT NULL,_change jsonb DEFAULT NULL,_preview uuid DEFAULT NULL,_confirmation text DEFAULT NULL,_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record;before_ jsonb;after_ jsonb;units_ jsonb;id_ uuid;rev_ bigint;fingerprint_ text;BEGIN
 IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Vui lòng đăng nhập lại.';END IF;IF _phase NOT IN ('preview','apply') THEN RAISE EXCEPTION 'Giai đoạn không hợp lệ.';END IF;
 PERFORM pg_advisory_xact_lock(hashtext('canonical_org')); PERFORM pg_advisory_xact_lock(hashtext('base_org')); PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));
 LOCK TABLE org_units,org_titles,org_assignments,base_org_state,biz_systems,biz_departments,biz_teams,biz_positions,biz_appointments,biz_department_members,biz_team_members,biz_member_affiliations,biz_management_assignments,biz_department_system_history,base_title_role_links IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE profiles,user_roles,app_roles,biz_approval_workflows,biz_access_exceptions IN SHARE MODE;
 SELECT revision INTO rev_ FROM private.org_control WHERE id FOR UPDATE;before_:=private.org_config();fingerprint_:=private.org_fingerprint();
 IF _phase='preview' THEN IF _revision IS DISTINCT FROM rev_ THEN RAISE EXCEPTION 'Nguồn cơ cấu đã thay đổi; xem trước lại.';END IF;INSERT INTO private.org_previews(actor_id,revision,baseline,changes,impact,next_transition_at) VALUES(auth.uid(),rev_,fingerprint_,_change,'{}',(SELECT min(ts) FROM (SELECT starts_at ts FROM org_assignments UNION ALL SELECT ends_at FROM org_assignments)x WHERE ts>clock_timestamp())) RETURNING id INTO id_;
 BEGIN INSERT INTO private.org_execution(transaction_id,actor_id,preview_id) VALUES(txid_current(),auth.uid(),id_);units_:=private.org_commands(_change);after_:=private.org_config();RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='rollback preview';EXCEPTION WHEN SQLSTATE 'ZX001' THEN NULL;END;
 UPDATE private.org_previews SET impact=jsonb_build_object('before',before_,'after',after_,'units',units_) WHERE id=id_;RETURN jsonb_build_object('id',id_,'revision',rev_,'impact','[]'::jsonb,'before',before_,'after',after_,'units',units_,'expires_at',clock_timestamp()+interval '10 minutes');
 END IF;
 SELECT * INTO p FROM private.org_previews WHERE id=_preview AND actor_id=auth.uid() FOR UPDATE;IF NOT FOUND OR p.applied_at IS NOT NULL OR p.expires_at<=clock_timestamp() OR p.next_transition_at<=clock_timestamp() THEN RAISE EXCEPTION 'Xem trước hết hạn/đã dùng hoặc hiệu lực đã thay đổi.';END IF;
 IF p.revision<>rev_ OR p.baseline<>fingerprint_ THEN RAISE EXCEPTION 'Nguồn cơ cấu/quyền đã thay đổi; xem trước lại.';END IF;IF coalesce(trim(_reason),'')='' OR _confirmation IS DISTINCT FROM 'ÁP DỤNG CƠ CẤU' THEN RAISE EXCEPTION 'Cần lý do và xác nhận ÁP DỤNG CƠ CẤU.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(p.changes) x WHERE x->>'action'='roles') AND _reason NOT LIKE 'ÁP DỤNG PHÂN QUYỀN:%' THEN RAISE EXCEPTION 'Thay đổi Role cần xác nhận ÁP DỤNG PHÂN QUYỀN: và lý do.';END IF;
 INSERT INTO private.org_execution(transaction_id,actor_id,preview_id) VALUES(txid_current(),auth.uid(),p.id);units_:=private.org_commands(p.changes);after_:=private.org_config();IF after_ IS DISTINCT FROM p.impact->'after' THEN RAISE EXCEPTION 'Tác động đã thay đổi; cần xem trước lại.';END IF;
 UPDATE private.org_control SET revision=rev_+1 WHERE id;INSERT INTO org_events(actor_id,before_revision,after_revision,unit_ids,reason,before_data,after_data) VALUES(auth.uid(),rev_,rev_+1,units_,trim(_reason),before_,after_);UPDATE private.org_previews SET applied_at=clock_timestamp() WHERE id=p.id;DELETE FROM private.org_execution WHERE transaction_id=txid_current();RETURN jsonb_build_object('revision',rev_+1);END $$;
REVOKE ALL ON FUNCTION private.org_fingerprint(),private.org_execution_ok(),private.org_projection_guard(),private.org_require(text,text),private.org_biz_appointment(jsonb,uuid),private.org_commands(jsonb) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION org_change(text,bigint,jsonb,uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION org_change(text,bigint,jsonb,uuid,text,text) TO authenticated,service_role;